void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Определение координаты центра
    vec2 center = vec2(0.5);

    // Определение величины смещения
    float offset = sin(iTime) * 0.1;

    // Перемещение координаты центра
    center.x += offset;

    // Определение цвета пикселя
    vec3 color = vec3(0.0);

    // Создание узора с использованием теории групп
    float distance = length(fragCoord - center);
    if(mod(distance, 0.1) < 0.05) {
        color = vec3(1.0);
    }

    // Присвоение цвета пикселю
    fragColor = vec4(color, 1.0);
}
